def f(name, label, default, kind="text"):
    return dict(name=name, label=label, default=default, kind=kind)


def lab(number, slug, title, category, level, kind, summary, mechanism, fields, normal,
        steps, expected, mitigation, boundary, reference, topic):
    return dict(id=f"{number:02d}_{slug}", title=title, category=category, level=level, kind=kind,
                summary=summary, mechanism=mechanism, fields=fields, normal=normal, steps=steps,
                expected=expected, mitigation=mitigation, boundary=boundary,
                reference_url=reference, cwe=topic, duration=25 if level == "Dasar" else 45 if level == "Menengah" else 60)


